/bin/bash -lc "python -B - <<'PY'
import io
import json
import urllib.error
from unittest.mock import Mock
from openai_client import OpenAIClient, OpenAIError, _NoRedirect

client = OpenAIClient('test-key')
def respond(value):
    client._opener = Mock()
    client._opener.open.return_value = io.BytesIO(json.dumps(value).encode())
respond({'status':'completed','output':[{'type':'reasoning'},{'type':'message','content':[{'type':'output_text','text':'Hello '},{'type':'output_text','text':'world'}]}]})
assert client.send_text('private text', model='test-model') == 'Hello world'
req = client._opener.open.call_args.args[0]
assert req.full_url == 'https://api.openai.com/v1/responses'
assert json.loads(req.data) == {'input':'private text','model':'test-model','store':False}
assert req.get_header('Authorization') == 'Bearer test-key'
for result in ({'status':'incomplete'}, {'status':'completed','output':[]}, {'status':'completed','output':[{'type':'message','content':[{'type':'refusal','refusal':'private text'}]}]}, []):
    respond(result)
    try:
        client.send_text('private text', model='test-model')
    except OpenAIError as exc:
        assert 'private text' not in str(exc)
    else:
        raise AssertionError('Expected error')
for error in (urllib.error.HTTPError(req.full_url, 401, 'private text', {}, io.BytesIO(b'private text')), urllib.error.URLError('private text')):
    client._opener.open.side_effect = error
    try:
        client.send_text('private text', model='test-model')
    except OpenAIError as exc:
        assert 'private text' not in str(exc)
        assert exc.__context__ is None
    else:
        raise AssertionError('Expected error')
client._opener.open.side_effect = None
client._opener.open.return_value = io.BytesIO(b'private text')
try:
    client.send_text('private text', model='test-model')
except OpenAIError as exc:
    assert exc.__context__ is None
assert _NoRedirect().redirect_request(req, None, 302, '', {}, 'https://example.com') is None
for timeout in (0, -1, True, float('inf')):
    try:
        OpenAIClient('test-key', timeout=timeout)
    except ValueError:
        pass
    else:
        raise AssertionError('Invalid timeout accepted')
print('Mocked request, extraction, privacy, error, redirect, and validation checks passed.')
PY"

